import pandas as pd, numpy as np
tr=pd.read_csv('b3_te_zt900_train.csv'); p=pd.read_csv('b3_te_zt900_pool.csv');
print('Training shape',tr.shape,'Missing',tr.isna().sum().sum());print(tr.target.describe());
fmt=lambda row:' '.join(f'{c}={v:.6g}' for c,v in row.items() if v!=0)
print('\nTOP 65 TRAIN:')
for i,row in tr.nlargest(65,'target').iterrows():print(i,round(row.target,5),fmt(row.drop('target')))
